// Analyze question and determine optimal top_k
const question = $json.body.chatInput || '';
const lowerQ = question.toLowerCase();

let top_k = 10;
if (lowerQ.includes('szczegół') || lowerQ.includes('jak') || lowerQ.includes('porówn')) {
  top_k = 15;
} else if (lowerQ.includes('przykład') || lowerQ.includes('lista')) {
  top_k = 12;
}

return {
  json: {
    query: question,
    top_k: top_k
  }
};

// Get embedding response from Fireworks
const responseInfo = $input.item.json;
const params = $('Code: Analyze Question').item.json;

// --- 1. EXTRACT VECTOR FROM FIREWORKS RESPONSE ---
let vector;
if (responseInfo.data && responseInfo.data[0] && responseInfo.data[0].embedding) {
  vector = responseInfo.data[0].embedding;
} else if (Array.isArray(responseInfo)) {
  vector = responseInfo;
} else {
  throw new Error('Brak wektora z API Fireworks. Response: ' + JSON.stringify(responseInfo).substring(0, 200));
}

// --- 2. BUILD QDRANT QUERY (NAMED VECTORS) ---
const qdrantQuery = {
  vector: {
    name: "dense",
    vector: vector
  },
  limit: params.top_k || 10,
  with_payload: true,
  score_threshold: 0.3
};

return {
  json: {
    qdrantQuery,
    originalQuestion: params.query,
    top_k: params.top_k
  }
};

// Format Qdrant results for LLM context
const response = $input.item.json;
const originalQuestion = $('Code: Prepare Qdrant Query').item.json.originalQuestion;

// Check for results
if (!response || !response.result || response.result.length === 0) {
  return {
    json: {
      context: 'Brak wyników. System RAG nie znalazł odpowiednich artykułów.',
      hasResults: false,
      resultCount: 0,
      results: [],
      originalQuestion
    }
  };
}

const results = response.result;

// Build formatted context
let context = `Znaleziono ${results.length} wyników z bazy wiedzy:\n\n`;
const formattedResults = [];

results.forEach((hit, index) => {
  const payload = hit.payload || {};

  context += `--- Wynik ${index + 1} (Score: ${(hit.score * 100).toFixed(1)}%) ---\n`;
  context += `Tytuł: ${payload.title || 'Brak tytułu'}\n`;
  context += `URL: ${payload.url || ''}\n`;
  context += `Typ sekcji: ${payload.section_type || 'content'}\n`;

  if (payload.publication_date) {
    context += `Data publikacji: ${payload.publication_date}\n`;
  }

  if (payload.tags && payload.tags.length > 0) {
    context += `Tagi: ${payload.tags.join(', ')}\n`;
  }

  if (payload.categories && payload.categories.length > 0) {
    context += `Kategorie: ${payload.categories.join(', ')}\n`;
  }

  context += `\nTreść:\n${payload.text || ''}\n\n`;

  formattedResults.push({
    title: payload.title || 'Brak tytułu',
    url: payload.url || '',
    score: hit.score,
    text: payload.text || '',
    section_type: payload.section_type || 'content'
  });
});

return {
  json: {
    context,
    hasResults: true,
    resultCount: results.length,
    results: formattedResults,
    originalQuestion
  }
};

// Format Chat History from webhook payload
const context = $json.context;
const chatInput = $('Webhook: RAG Question').item.json.body.chatInput;
const chatHistoryArray = $('Webhook: RAG Question').item.json.body.chatHistory || [];

// Format history as text
let chatHistoryText = '';
if (chatHistoryArray && chatHistoryArray.length > 0) {
  chatHistoryArray.forEach(msg => {
    const role = msg.role === 'user' ? 'Użytkownik' : 'Asystent';
    chatHistoryText += `${role}: ${msg.content}\n\n`;
  });
} else {
  chatHistoryText = 'Brak poprzedniej rozmowy.';
}

return {
  json: {
    context,
    chatInput,
    chat_history: chatHistoryText
  }
};
